static inline int Sdb_CutSetAddCut( Sdb_Cut_t ** pCuts, int nCuts, int nCutNum )
{
    if ( nCuts == 0 )
        return 1;
    nCuts = Sdb_CutSetLastCutContains(pCuts, nCuts);
    assert( nCuts >= 0 );
